use super::*;

fn generate_ts(src: &str) -> Result<String, Vec<Diagnostic>> {
    let (ast, diags) = brim_parser::parse(src);
    assert!(diags.is_empty(), "{diags:?}");
    let modules = [brim_semantic::ModuleAst {
        name: String::new(),
        program: ast,
    }];
    let (checked, diags) = brim_semantic::check_tests(&modules);
    let checked = checked.unwrap_or_else(|| panic!("{diags:?}"));
    generate(&checked, |_| true, "api.brim", Options::default())
}

const HEADER: &str = "// TypeScript types for the API of api.brim.\n\
                      // Generated by `brim gen ts`; do not edit.\n\
                      // i64 values become numbers: beyond 2^53 they lose precision.\n";

#[test]
fn structs_and_enums() {
    let src = r#"
pub struct User {
    id: i64,
    name: string,
    admin: bool,
    tags: List[string],
    scores: Map[string, i64],
    manager: Option[i64],
    role: Role,
}

pub enum Role {
    Guest,
    Member,
}

pub enum Event {
    Joined(User),
    Moved(i64, i64),
    Left,
}

struct Internal {
    secret: string,
}
"#;
    assert_eq!(
        generate_ts(src).unwrap(),
        format!(
            "{HEADER}
export interface User {{
  id: number;
  name: string;
  admin: boolean;
  tags: string[];
  scores: Record<string, number>;
  manager: number | null;
  role: Role;
}}

export type Role = \"Guest\" | \"Member\";

export type Event =
  | {{ kind: \"Joined\"; value: User }}
  | {{ kind: \"Moved\"; value: [number, number] }}
  | {{ kind: \"Left\" }};
"
        )
    );
}

#[test]
fn generics_and_used_types() {
    let src = r#"
pub struct Page[T] {
    items: List[T],
    next: Option[string],
}

pub struct Reply {
    users: Page[Name],
    outcome: Result[i64, string],
    flags: Map[bool, List[Option[i64]]],
}

struct Name {
    first: string,
}
"#;
    assert_eq!(
        generate_ts(src).unwrap(),
        format!(
            "{HEADER}
export interface Page<T> {{
  items: T[];
  next: string | null;
}}

export interface Reply {{
  users: Page<Name>;
  outcome: {{ kind: \"Ok\"; value: number }} | {{ kind: \"Err\"; value: string }};
  flags: Partial<Record<\"true\" | \"false\", Array<number | null>>>;
}}

export interface Name {{
  first: string;
}}
"
        )
    );
}

#[test]
fn only_selected_modules() {
    let (ast, _) = brim_parser::parse("pub struct A {\n    x: i64,\n}\n");
    let (other, _) = brim_parser::parse("pub struct B {\n    y: i64,\n}\n");
    let modules = [
        brim_semantic::ModuleAst {
            name: String::new(),
            program: ast,
        },
        brim_semantic::ModuleAst {
            name: "dep".into(),
            program: other,
        },
    ];
    let (checked, _) = brim_semantic::check_tests(&modules);
    let out = generate(&checked.unwrap(), |m| m == 0, "x", Options::default()).unwrap();
    assert!(out.contains("interface A"));
    assert!(!out.contains("interface B"));
}
